%[text] # Simplistic Vehicle - Simulation Case
%[text] Note that vehicle dynamics and temperature dynamics are isolated from each other in the model, and it is intentional.
mdl = "HarnessModel_CtrlEnv_Vehicle";
load_system(mdl)

CtrlEnv_Vehicle_params

initial.VehicleSpeed_kph = 0;

TireRollingRadius_m = 0.35;
GearRatio = 9.1;

initial.VehicleInertiaSpd_rpm = CtrlEnv_Vehicle_getMotorSpeedFromVehicleSpeed( ...
  VehicleSpeed_kph = initial.VehicleSpeed_kph, ...
  TireRollingRadius_m = TireRollingRadius_m, ...
  GearRatio = GearRatio );

initial.MotorTemperature_K = 273.15 + 70;
initial.BatteryTemperature_K = 273.15 + 50;

initial.MotorAmbientTemperature_K = 273.15 + 20;
initial.BatteryAmbientTemperature_K = initial.MotorAmbientTemperature_K;

sim_in = Simulink.SimulationInput(mdl);
sim_in = setModelParameter(sim_in, StopTime = "300");

sim_out = sim(sim_in);
sim_data = extractTimetable(sim_out.logsout);

signal_names = [
  "Brake force"
  "Motor torque command"
  "Motor heat flow command"
  "Battery heat flow command"
  "Vehicle speed kph"
  "Motor speed"
  "Motor temperature"
  "Battery temperature"
  ];

for idx = 1 : numel(signal_names) %[output:group:0b2a4893]
  SignalTool3.plotTimedData( TimedData = sim_data, ... %[output:1d966749] %[output:09f237eb] %[output:327f760a] %[output:84990d61] %[output:23d9efab] %[output:0be952d6] %[output:64e3d840] %[output:925b92ee]
    SignalName = signal_names(idx), ... %[output:1d966749] %[output:09f237eb] %[output:327f760a] %[output:84990d61] %[output:23d9efab] %[output:0be952d6] %[output:64e3d840] %[output:925b92ee]
    FigureHeight = 200 ) %[output:1d966749] %[output:09f237eb] %[output:327f760a] %[output:84990d61] %[output:23d9efab] %[output:0be952d6] %[output:64e3d840] %[output:925b92ee]
end  % for %[output:group:0b2a4893]
